// src/core/measured.js is generated by scripts/eval.mjs and read through families.js. Its shape is
// a contract with the window and the options page.
import test from "node:test";
import assert from "node:assert/strict";
import { MEASURED, MEASURED_AT, MEASURED_DETAIL, MEASURED_DOES_NOT_PROVE } from "../src/core/measured.js";
import { measuredLine } from "../src/core/families.js";

test("every row is a held-out test measurement with a valid interval", () => {
  assert.match(MEASURED_AT, /^\d{4}-\d{2}-\d{2}$/);
  for (const [f, r] of Object.entries(MEASURED)) {
    assert.equal(r.split, "test", f);
    assert.ok(Number.isInteger(r.n) && r.n >= 20, f);
    assert.ok(r.low <= r.precision && r.precision <= r.high && r.low >= 0 && r.high <= 1, f);
    assert.equal(measuredLine(f).measured, true, f);
  }
});

test("the strong rhetoric families with enough hits are measured", () => {
  for (const f of ["slur", "dehumanise", "violence", "stereotype"]) assert.ok(MEASURED[f], f);
});

test("synthetic pilots never appear as measured precision", () => {
  assert.equal(MEASURED.duplicates, undefined);
  assert.equal(MEASURED.mismatch, undefined);
  assert.equal(MEASURED_DETAIL.duplicates.synthetic, true);
  assert.equal(MEASURED_DETAIL.mismatch.synthetic, true);
  assert.equal(measuredLine("mismatch").text, "not measured yet");
});

test("the detail keeps the split, the side comparison and a does-not-prove line", () => {
  assert.equal(MEASURED_DETAIL.split, "test");
  assert.ok(MEASURED_DETAIL.sides.mhs.left.recall && MEASURED_DETAIL.sides.mhs.right.recall);
  assert.ok(MEASURED_DOES_NOT_PROVE.length > 40);
  assert.ok(!/\u2014/.test(MEASURED_DOES_NOT_PROVE), "no em dashes in user-facing text");
});

test("the persuasion block survives a rewrite of measured.js by scripts/eval.mjs", async () => {
  const { readFileSync } = await import("node:fs");
  const { currentBlock, persuasionBlock } = await import("../scripts/eval/summarise-persuasion.mjs");
  const { MEASURED_PERSUASION } = await import("../src/core/measured.js");
  const src = readFileSync(new URL("../src/core/measured.js", import.meta.url), "utf8").split("\r\n").join("\n");
  assert.equal(currentBlock(src), persuasionBlock(MEASURED_PERSUASION));
  for (const id of Object.keys(MEASURED_PERSUASION)) assert.equal(MEASURED[id], undefined, `${id} stays out of MEASURED`);
});
